import { sql } from "drizzle-orm";
import { timestamp, uuid } from "drizzle-orm/pg-core";

/** UUID v7 primary key (CLAUDE.md §9), generated by Postgres 18 `uuidv7()`. Never shown to users. */
export const id = () =>
  uuid("id")
    .primaryKey()
    .default(sql`uuidv7()`);

/** timestamptz in UTC; `updated_at` is maintained by the `set_updated_at` trigger. */
export const timestamps = {
  createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
  updatedAt: timestamp("updated_at", { withTimezone: true }).notNull().defaultNow(),
};

/** A nullable timestamptz column. */
export const tsz = (name: string) => timestamp(name, { withTimezone: true });

/** SQL fragment: text is present and not only spaces. */
export const filled = (column: unknown) => sql`(${column} IS NOT NULL AND btrim(${column}) <> '')`;
